mapper.select:
select * from iot_device_log_metadata


    AND iot_id = #{iotId}


    AND message_type = #{messageType}


    AND property = #{property}


    AND event = #{event}


    AND product_key = #{productKey}


    AND device_id = #{deviceId}


    AND create_time >= #{beginTime,jdbcType=TIMESTAMP}


    AND create_time <= #{endTime,jdbcType=TIMESTAMP}


ORDER BY create_time DESC, id DESC


SELECT create_time
FROM iot_device_log_metadata
WHERE iot_id = #{iotId}
  AND message_type = 'EVENT'
  AND event = #{event}
ORDER BY id desc LIMIT 1

select.foreach:
SELECT #{window.index,jdbcType=INTEGER} AS window_index, sample.content
FROM (
  SELECT CASE WHEN LENGTH(content) <= 1024 THEN content END AS content
  FROM iot_device_log_metadata
  WHERE iot_id = #{iotId} AND property = #{property}
    AND product_key = #{productKey} AND message_type = 'PROPERTIES'
    AND device_id = #{deviceId}
    AND create_time >= #{window.beginTime,jdbcType=TIMESTAMP}
    AND create_time < #{window.endExclusiveTime,jdbcType=TIMESTAMP}
    AND create_time <= #{endTime,jdbcType=TIMESTAMP}
  ORDER BY create_time DESC, id DESC LIMIT #{sampleFetchSize}
) AS sample

mapper.select:
SELECT * FROM iot_device_log_metadata
WHERE iot_id = #{iotId} AND product_key = #{productKey}
  AND create_time >= #{beginTime,jdbcType=TIMESTAMP}
  AND create_time <= #{endTime,jdbcType=TIMESTAMP}
  AND device_id = #{deviceId}
  AND message_type = #{messageType}
  AND event = #{event}
  AND property = #{property}

    AND create_time <= #{beforeTime,jdbcType=TIMESTAMP}
    AND (create_time < #{beforeTime,jdbcType=TIMESTAMP}
      OR (create_time = #{beforeTime,jdbcType=TIMESTAMP} AND id < #{beforeId,jdbcType=BIGINT}))

ORDER BY create_time DESC, id DESC LIMIT #{fetchSize}
